/**
 * Linarc wordmark (mark + "LINARC") for a dark/black bar — e.g. the Project List's branded
 * header. Traced from the Figma "Linarc Logo on Dark Header" export at its native 126x32
 * viewBox: the mark stays brand orange, the letterforms render in white.
 */
@Composable
fun LinarcWordmarkOnDark(modifier: Modifier = Modifier) {
    val markPath = remember { PathParser().parsePathString(MarkPathData).toPath() }
    val letterPaths = remember { WordmarkLetterPathData.map { PathParser().parsePathString(it).toPath() } }

    Canvas(
        modifier = modifier
            .aspectRatio(WordmarkViewboxWidth / WordmarkViewboxHeight, matchHeightConstraintsFirst = true)
            .semantics { contentDescription = "Linarc" }
            .testTag("linarcWordmark"),
    ) {
        val fit = size.width / WordmarkViewboxWidth
        scale(fit, fit, pivot = Offset.Zero) {
            drawPath(markPath, LinarcOrange)
            letterPaths.forEach { drawPath(it, OnDark) }
        }
    }
}
